INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-21', 'INSURANCE', '종합위험 밭작물 수확감소보장', '§4 1. 종합위험 수확감소보장 (대상품목 18종 — 고구마/옥수수/사료용옥수수/콩/양배추(가을·월동)/양파/마늘/차(茶)/감자(봄·고랭지·가을)/팥/수박(노지)/단호박/참깨/당근(가을·월동·고랭지)/녹두/생강/가을무(일반무)/가을배추(병충해보장형 포함)). 26년 신규 = 녹두/생강/참깨. 보장 = 보험기간 내 보장재해로 피해율이 자기부담비율을 초과 시 수확감소보험금 지급. 부속 보장 = 조기파종(마늘 난지)/재파종/재정식/경작불능/수확감소.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-22', 'INSURANCE', '종합위험 밭작물 생산비보장', '§4 2. 종합위험 생산비보장방식 (대상품목 — 고추/브로콜리/배추(고랭지·월동·봄)/무(고랭지·월동·가을(단무지·알타리))/대파/쪽파·실파(1형)/메밀/시금치(노지)/양상추). 보장 = 보장재해로 사고 발생 시점까지 투입된 작물의 생산비를 피해율에 따라 지급. 부속 = 재정식·재파종/경작불능/생산비보장 손해조사(고추·브로콜리는 사고접수 직후, 그 외는 수확직전).', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.549', 549, 556, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-23', 'INSURANCE', '작물특정 인삼손해보장', '§4 3. 작물특정 및 시설종합위험 인삼손해보장방식 — 작물(인삼) 부분. 보장재해 9종(태풍·강풍/폭설/집중호우/침수/화재/우박/냉해/폭염/조수해)으로 인삼에 직접적인 피해 발생 시 자기부담비율 초과분에 대해 보험금 지급. 본 BATCH 영역은 도입까지 (p.567~569) — 산식·수확량조사 본문은 BATCH-5 영역.', '작물특정 인삼손해보장', NULL, NULL, 'p.567', 567, 574, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-24', 'INSURANCE', '시설(해가림시설) 종합위험 손해보장', '§4 3. 작물특정 및 시설종합위험 인삼손해보장방식 — 시설(해가림시설) 부분. 보장재해 3종(자연재해/조수해/화재)으로 해가림시설(시설)에 직접 피해 발생 시 자기부담금 초과분에 대해 보험금 지급. 보험가입금액 ≥ 보험가액 시 손해액 - 자기부담금. 가입금액 < 가액 시 가입금액 한도 비례보상. 본 BATCH 영역은 도입까지.', '시설(해가림시설) 종합위험 손해보장', NULL, NULL, 'p.567', 567, 574, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-25', 'INSURANCE', '마늘 조기파종특약 (특별약관)', 'INS-21 종합위험 밭작물 수확감소보장의 부속 특별약관 — 조기파종보장 특별약관 판매시기 중 가입한 남도종(난지형) 마늘 재배 제주도 지역 농지 한정. (1) 한지형 마늘 최초 판매개시일 24시 이전에 보장재해로 10a당 식물체 주수가 30,000주 미만 발생 후 10월 31일 이전 30,000주 이상 재파종 → 재파종보험금 = 보험가입금액 × 25% × 표준 피해율 (난지형 마늘만 적용) / (2) 식물체 피해율 65% 이상 발생 → 경작불능보험금 (자기부담비율별 32/30/28/25/25%, 산지폐기 확인 시 지급).', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.538', 538, 545, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-028', 'CROP', '고구마', '§4 종합위험 수확감소보장 대상. 표본구간 수확량 = 정상 + 50%형 × 0.5 + 80%형 × 0.2. 수확량조사 적기 = 비대 종료 시점 (삽식일+120일). 자기부담비율별 보장비율 1군 (10%형 45/15%형 42/20%형 40/30%형 35/40%형 30%).', '종합위험 밭작물 수확감소보장', '고구마', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-029', 'CROP', '옥수수', '§4 종합위험 수확감소보장 대상 (사료용 옥수수와 분리). 수확감소보험금 = MIN[보험가입금액, 손해액] - 자기부담금 (특수 산식). 손해액 = 피해수확량 × 가입가격. 표본구간 피해수확량 = (하 항목 개수 + 중 항목 개수 × 0.5) × 품종별 표준중량 × 재식시기지수 × 재식밀도지수. 표준중량(g): 미백2호 180/대학찰(연농2호) 160/미흑찰 등 190.', '종합위험 밭작물 수확감소보장', '옥수수', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-030', 'CROP', '사료용 옥수수', '§4 종합위험 수확감소보장 대상 (옥수수와 분리, 수확량조사 제외). 경작불능보험금 = 보험가입금액 × 보장비율 × 경과비율. 보장비율 (45%/42%/40%/35%/30%형) × 월별 경과비율 (5월 80%/6월 80%/7월 90%/8월 100%).', '종합위험 밭작물 수확감소보장', '사료용 옥수수', NULL, 'p.541', 541, 548, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-031', 'CROP', '콩', '§4 종합위험 수확감소보장 대상. 표본조사+전수조사 (점파/산파). 표본 종실중량 = 표본구간 종실중량 × (1 - 함수율) ÷ 0.86. 전수조사 = 기계수확(탈곡 포함) 또는 자른 작물 그대로 둔 상태 기계탈곡 농지 한정. 콩 수확 적기 = 콩잎이 누렇게 변하여 떨어지고 꼬투리 80~90% 이상이 고유 성숙(황색)색깔로 변하는 시기인 생리적 성숙기로부터 7~14일 지난 시기.', '종합위험 밭작물 수확감소보장', '콩', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-032', 'CROP', '양배추(가을·월동)', '§4 종합위험 수확감소보장 대상. 표본구간 수확량 = 표본구간별 정상 양배추 무게의 합계 + 80%형 양배추의 무게 × 0.2. 수확량조사 적기 = 결구 형성이 완료된 때. 재정식 대상.', '종합위험 밭작물 수확감소보장', '양배추', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-033', 'CROP', '양파', '§4 종합위험 수확감소보장 대상. 표본구간 수확량 = 작물 무게 × (1 + 누적비대추정지수). 비대지수 2.2%/1일. 양파 비대 종료(식물체 도복 완료) 시점이 수확량조사 적기. 양파 최대지름 6cm 미만 = 80%(가공용 가능)/100%(가공용 불가) 피해 인정 → 무게의 20%/0%만 수확량으로 인정.', '종합위험 밭작물 수확감소보장', '양파', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-034', 'CROP', '마늘', '§4 종합위험 수확감소보장 대상. 표본구간 수확량 = 작물 무게 × (1 + 누적비대추정지수) × 환산계수 (난지형·홍산 0.72/한지형 0.7). 비대지수 0.8%/1일. 마늘 비대 종료 = 잎과 줄기가 1/2~2/3 황변하여 말랐을 때 + 통상 수확기 도래. 마늘통 최대지름 한지형 2cm/난지형 3.5cm 미만 = 80%/100% 피해 인정 → 20%/0% 수확량 인정. 재파종(난지형만) = 보험가입금액 × 35% × 표준 피해율(10a 30,000주 기준).', '종합위험 밭작물 수확감소보장', '마늘', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-035', 'CROP', '차(茶)', '§4 종합위험 수확감소보장 대상. 표본구간 수확량 = 수확한 새싹 무게/수확수 × (기수확수 × 기수확지수) + 수확한 새싹 무게. 표본조사 only (전수조사 X). 표본 = 0.04㎡ 테, 표본구간 면적 합계 산정 = 표본구간수 × 0.08㎡. 신초장 4.8cm 이상/엽장 2.8cm 이상/엽폭 0.9cm 이상 1심2엽 형성 시점이 수확가능. 5월 10일 한도. 기수확지수표 10단계 (10% 미만 1.000 → 90% 이상 0.924).', '종합위험 밭작물 수확감소보장', '차(茶)', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-036', 'CROP', '감자(봄재배)', '§4 종합위험 수확감소보장 대상. 감자 피해율 특수 산식 = {(평년수확량 - 수확량 - 미보상감수량) + 병충해감수량} ÷ 평년수확량 (병충해 가산). 병충해감수량 = 병충해 입은 괴경의 무게 × 손해정도비율 × 인정비율(1급 90%/2급 70%/3급 50%). 표본구간 = 정상/병충해별 11단계(10% 이하~91~100% 이하). 봄재배 수확량조사 적기 = 비대 종료(파종일+95일).', '종합위험 밭작물 수확감소보장', '감자(봄재배)', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-037', 'CROP', '감자(고랭지재배)', '§4 종합위험 수확감소보장 대상. 감자 공통 피해율 산식 적용 (병충해감수량 가산). 고랭지재배 수확량조사 적기 = 비대 종료(파종일+110일).', '종합위험 밭작물 수확감소보장', '감자(고랭지재배)', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-038', 'CROP', '감자(가을재배)', '§4 종합위험 수확감소보장 대상. 감자 공통 피해율 산식 적용. 가을재배 수확량조사 적기 = 비대 종료(파종일+제주 110일/이외 95일). 재파종 보험금 = 보험가입금액 × 20% × 면적피해율 ★ 26년 개정 (가을무와 동일 패턴 신규).', '종합위험 밭작물 수확감소보장', '감자(가을재배)', NULL, 'p.540', 540, 547, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-039', 'CROP', '팥', '§4 종합위험 수확감소보장 대상. 표본조사+전수조사 (점파/산파, 콩과 동일). 표본 종실중량 = 표본구간 종실중량 × (1 - 함수율) ÷ 0.86. 팥 수확 적기 = 꼬투리 70~80% 이상이 성숙한 시기. 경작불능 = 보험가입금액 × 자기부담비율별 보장비율(콩과 동일 1군).', '종합위험 밭작물 수확감소보장', '팥', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-040', 'CROP', '수박(노지)', '§4 종합위험 수확감소보장 대상. 표본구간 수확량 = 수박 무게(줄기 절단 X) 합계, 보장재해로 일반시장 출하 불가능 + 가공용 불가 = 무게의 0% 인정. 수확 적기 = 꽃가루받이 후 또는 착과 후 35~45일.', '종합위험 밭작물 수확감소보장', '수박(노지)', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-041', 'CROP', '단호박', '§4 종합위험 수확감소보장 대상. 표본구간 수확량 = 과병부(꼭지) 절단 후 단호박 무게 합계. 일반시장 + 가공용 불가 = 0% 인정. 수확 적기 = 과병부가 세로로 갈색 균열 발생 시기. 재정식 대상.', '종합위험 밭작물 수확감소보장', '단호박', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-042', 'CROP', '참깨 ★ 26년 신규', '§4 종합위험 수확감소보장 대상 ★ 26년 신규 품목 (4월8일 변경사항정리 §11 보장방식변경: 생산비보장 → 수확감소보장). 표본 종실중량 = 표본구간 종실중량 × (1 - 함수율) ÷ 0.9. 참깨 수확 적기 = 아랫 단 꼬투리 2~3개가 벌어지는 시기(7월말~8월말). 경작불능 자기부담비율별 보장비율 2군 (-/-/40/35/30%).', '종합위험 밭작물 수확감소보장', '참깨', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-043', 'CROP', '당근(고랭지)', '§4 종합위험 수확감소보장 대상. 표본구간 수확량 = 정상 + 80%피해 당근 무게 × 0.2 (양배추와 유사). 수확 적기 = 겉잎이 지면에 닿을 정도로 늘어진 시기. 재파종 = 보험가입금액 × 15% × 면적피해율 (자기부담비율 초과 트리거).', '종합위험 밭작물 수확감소보장', '당근(고랭지)', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-044', 'CROP', '당근(가을·월동)', '§4 종합위험 수확감소보장 대상. 표본구간 수확량 = 정상 + 80%피해 당근 × 0.2. 재파종 = 보험가입금액 × 15% × 면적피해율 (고랭지당근과 동일).', '종합위험 밭작물 수확감소보장', '당근(가을·월동)', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-045', 'CROP', '녹두 ★ 26년 신규', '§4 종합위험 수확감소보장 대상 ★ 26년 신규 품목 (4월8일 변경사항정리 §11 신규품목 — 종합위험 수확감소보장방식 신설). 표본 종실중량 = 표본구간 종실중량 × (1 - 함수율) ÷ 0.87. 녹두 수확 적기 = 8월 초~10월(생육 정지(수확 예정 3~4일 전 염수 살포 등) + 일시수확(기계수확) 가능 + 꼬투리 70~80% 이상이 고유 성숙(흑갈색)색깔로 변하는 시기). 표본조사 점파/산파. 자기부담비율별 보장비율 2군.', '종합위험 밭작물 수확감소보장', '녹두', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-046', 'CROP', '생강 ★ 26년 신규', '§4 종합위험 수확감소보장 대상 ★ 26년 신규 품목 (4월8일 변경사항정리 §11 신규품목 — 종합위험 수확감소보장방식 신설). 표본구간 수확량 = 생강 수확 후 덩이 + 윗부분 줄기 절단 무게 합계. 수확 적기 = 비대 종료(파종 후 180일). 경북지역은 10월 30일/충남지역 11월 초까지 수확 종료. 자기부담비율별 보장비율 2군.', '종합위험 밭작물 수확감소보장', '생강', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-047', 'CROP', '가을무(일반무)', '§4 종합위험 수확감소보장 대상. 표본구간 수확량 = 무청 제거 후 무게 합계. 수확 적기 = 결구 형성 완료. 재파종 = 보험가입금액 × 20% × 면적피해율 ★ 26년 신규 (4월8일 변경사항정리 §12 — 가을감자/가을무 추가). 보장개시일 +10일 (생산비보장→수확감소 변경 정합).', '종합위험 밭작물 수확감소보장', '가을무(일반무)', NULL, 'p.540', 540, 547, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-048', 'CROP', '가을배추(병충해보장형 포함)', '§4 종합위험 수확감소보장 대상. 표본구간 수확량 = 외엽 2겹 내외 제거 후 무게. 수확 적기 = 결구 형성 완료. 재정식 대상. 병충해보장형 = 예찰조사 분할평가 (재배초기/중기/수확기) + 병충해 보상. 보장개시일 +10일 (생산비보장→수확감소 변경 정합).', '종합위험 밭작물 수확감소보장', '가을배추', NULL, 'p.522', 522, 529, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-049', 'CROP', '고추', '§4 종합위험 생산비보장방식 대상. 생산비보장보험금 = (잔존보험가입금액 × 경과비율 × 피해율) - 자기부담금 (병충해 없음) / 병충해 있음 = ×병충해 등급별 인정비율. 경과비율 (수확기 이전) = 준비기생산비계수 54.2% + (1 - 54.2%) × (생장일수/표준생장일수). 표준생장일수 = 홍고추 100일/풋고추 70일. 수확기 중 = 1 - (수확일수/표준수확일수). 표준수확일수 ≤ 정식완료일+150일. 피해율 = 면적피해율 × 평균손해정도비율 × (1 - 미보상비율). 노지 고추만 병충해 등급별 인정비율 적용.', '종합위험 밭작물 생산비보장', '고추', NULL, 'p.562', 562, 569, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-050', 'CROP', '브로콜리', '§4 종합위험 생산비보장방식 대상. 생산비보장보험금 = (잔존보험가입금액 × 경과비율 × 피해율) - 자기부담금. 경과비율 (수확기 이전) = 준비기생산비계수 67.1% + (1 - 67.1%) × (생장일수/표준생장일수 130일). 수확기 중 = 1 - (수확일수/표준수확일수). 피해율 = 면적피해율 × 작물피해율 × (1 - 미보상비율). 작물피해율 = 피해송이 수 ÷ 총 송이 수. 피해인정계수 = 정상 0/50%형 0.5/80%형 0.8/100%형 1.', '종합위험 밭작물 생산비보장', '브로콜리', NULL, 'p.564', 564, 571, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-051', 'CROP', '배추(고랭지·월동·봄)', '§4 종합위험 생산비보장방식 대상. 생산비보장보험금 = 보험가입금액 × (피해율 - 자기부담비율). 피해율 = 면적피해율 × 평균손해정도비율 × (1 - 미보상비율). 면적피해율 = 피해면적 ÷ 재배면적. 표본이랑 조사. 손해정도비율표 = 26년 신규 10단계.', '종합위험 밭작물 생산비보장', '배추', NULL, 'p.549', 549, 556, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-052', 'CROP', '무(고랭지·월동·가을 단무지·알타리)', '§4 종합위험 생산비보장방식 대상. 생산비보장보험금 = 보험가입금액 × (피해율 - 자기부담비율). 표본구간 내 연속 10구 손해정도비율 조사. 손해정도비율표 26년 신규 10단계.', '종합위험 밭작물 생산비보장', '무', NULL, 'p.549', 549, 556, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-053', 'CROP', '대파', '§4 종합위험 생산비보장방식 대상. 표본구간 내 연속 50구 손해정도비율 조사 (대파/쪽파·실파 공통). 생산비보장보험금 = 보험가입금액 × (피해율 - 자기부담비율).', '종합위험 밭작물 생산비보장', '대파', NULL, 'p.549', 549, 556, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-054', 'CROP', '쪽파·실파(1형)', '§4 종합위험 생산비보장방식 대상. 대파와 동일 표본 50구 손해정도비율 조사. 1형 = 약관에서 정한 생장기간 단형.', '종합위험 밭작물 생산비보장', '쪽파·실파(1형)', NULL, 'p.549', 549, 556, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-055', 'CROP', '메밀', '§4 종합위험 생산비보장방식 대상. 생산비보장보험금 = 보험가입금액 × (피해율 - 자기부담비율). 피해율 = 면적피해율 × (1 - 미보상비율) (배추/무와 다른 단순 산식). 피해면적 = (도복 피해면적 × 70%) + (도복 이외 피해면적 × 평균손해정도비율). 도복면적 = 일괄 70% 손해정도비율 적용. 표본구간 = 1㎡ 원형 또는 가로·세로 1m × 1m.', '종합위험 밭작물 생산비보장', '메밀', NULL, 'p.565', 565, 572, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-056', 'CROP', '시금치(노지)', '§4 종합위험 생산비보장방식 대상. 표본이랑별 식재된 작물 손해정도비율 조사 (이랑길이 1m 간격으로 구획).', '종합위험 밭작물 생산비보장', '시금치(노지)', NULL, 'p.549', 549, 556, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-057', 'CROP', '양상추', '§4 종합위험 생산비보장방식 대상. 자기부담비율별 경작불능보험금 = 20%/30%/40%형만 적용 (10%/15%형 X). 생산비보장보험금 = 보험가입금액 × (피해율 - 자기부담비율).', '종합위험 밭작물 생산비보장', '양상추', NULL, 'p.561', 561, 568, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-058', 'CROP', '인삼', '§4 작물특정 인삼손해보장 대상 (특정위험 — 태풍/강풍/폭설/집중호우/침수/화재/우박/냉해/폭염/조수해 9종). 본 BATCH 영역 = 도입 + 시기별 조사 종류 + 최초가입 조사 + 피해사실 확인조사 도입까지 (p.567~569). 산식·수확량조사 본문 = BATCH-5 영역.', '작물특정 인삼손해보장', '인삼', NULL, 'p.567', 567, 574, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-059', 'CROP', '해가림시설 (시설)', '§4 시설 종합위험 손해보장 대상 (종합위험 — 자연재해/조수해/화재 3종). 작물 X, 시설 (인삼 재배 보호용 차광막·구조체). 본 BATCH 영역 = 도입까지. 산식 본문 = BATCH-5 영역.', '시설(해가림시설) 종합위험 손해보장', '해가림시설', NULL, 'p.567', 567, 574, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-055', 'INVESTIGATION', '밭작물 예찰조사', 'INS-21 종합위험 밭작물 수확감소보장 + INS-22 생산비보장 공통. 사고 미접수 상태에서 보험 목적 위험상태 조사. (1) 가입 전 사고발생 여부 / (2) 보장재해 피해여부 / (3) 그 외 원인 수확량 감소 영향 요인 확인. 가을배추(병충해보장형) 분할평가 = 재배초기/중기/수확기 방제노력 적정성.', '종합위험 밭작물 수확감소보장', NULL, '예찰조사', 'p.523', 523, 530, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-056', 'INVESTIGATION', '밭작물 피해사실 확인조사', 'INS-21 + INS-22 공통. 대상 재해 = 자연재해 / 조수해(鳥獸害) / 화재 / 병충해(감자·가을배추(병충해보장형)만). 추가조사 필요 여부 판단(재정식·재파종·경작불능·수확량). 태풍 등 재해 명확 시 생략 가능.', '종합위험 밭작물 수확감소보장', NULL, '피해사실 확인조사', 'p.523', 523, 530, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-057', 'INVESTIGATION', '재파종조사 (마늘·당근·가을무·감자(가을재배))', '전(前)조사 = 재파종 보험금 지급 대상 여부. 마늘(난지형) = 표본구간수 산정 + 식물체 8주 이상(또는 1m) 이랑 길이/폭/식물체 주수. 당근/가을무/감자(가을재배) = 피해면적 확인(GPS/지형도). 후(後)조사 = 재파종 이행완료 여부 + 표본구간별 파종주수 조사. 일부 재파종 시 미이행 면적 제외.', '종합위험 밭작물 수확감소보장', NULL, '재파종조사', 'p.524', 524, 531, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-058', 'INVESTIGATION', '재정식조사 (양배추·단호박·가을배추(병충해보장형 포함)·양파)', '전(前)조사 = 재정식 보험금 지급 대상 여부 (피해면적 GPS 확인). 후(後)조사 = 재정식 이행완료 여부. 일부 재정식 시 미이행 면적 제외. 농지별 상황에 따라 전조사 생략 후 후조사 시 면적조사 가능.', '종합위험 밭작물 수확감소보장', NULL, '재정식조사', 'p.526', 526, 533, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-059', 'INVESTIGATION', '밭작물 경작불능조사 (수확감소)', 'INS-21 종합위험 수확감소 대상 (콩/팥/옥수수(사료용)/고구마/감자/양파/마늘/양배추/수박/단호박/가을배추/가을배추(병충해보장형)/참깨/당근/가을무/생강/녹두). 식물체 피해율 65% 이상 + 계약자 신청. 65% 미만 또는 미신청 시 = 수확량조사 대상. 산지폐기 후(後)조사 = 시장 미유통 확인.', '종합위험 밭작물 수확감소보장', NULL, '경작불능조사', 'p.527', 527, 534, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-060', 'INVESTIGATION', '밭작물 수확량조사 (사료용 옥수수 제외)', 'INS-21 적용 18종(사료용 옥수수 제외). 수확 직전(차(茶)는 조사 가능 시기). 경작불능 보장 보험기간 내 식물체 피해율 65% 이상 시 콩/팥 한정 확인. 수확량조사 적기 표 — 양파(도복 완료)/마늘(잎과 줄기 1/2~2/3 황변)/고구마(삽식+120일)/감자(파종+95~110일)/옥수수(수염 후 25일)/콩(생리적 성숙기+7~14일)/팥(꼬투리 70~80% 성숙) 등. 면적 5단계 (실제경작/고사/타작물·미보상/기수확/조사대상). 표본조사 또는 전수조사 (콩·팥만).', '종합위험 밭작물 수확감소보장', NULL, '수확량조사', 'p.529', 529, 536, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-061', 'INVESTIGATION', '표본조사 (밭작물 수확감소)', 'INV-060 의 한 방법. 표본구간수 산정(별표1) + 표본구간 선정 + 표본구간 면적 + 수확량 조사. 양파/마늘은 비대지수 적용 (지역별 수확 적기보다 일찍 조사 시 잔여일수별). 표본구간 면적 산정 = 양파·마늘 이랑폭 2m미만(이랑길이 5주 이상) / 2m이상(3주 이상) / 단호박·당근 / 고구마·양배추·감자·옥수수 5주 이상 / 차(茶) 0.04㎡ 테 / 콩·팥 점파 4주 이상 + 산파 1㎡ / 수박·당근 10주 / 가을배추 6주 / 참깨·생강 4~5주 / 녹두 4주 + 산파 1㎡.', '종합위험 밭작물 수확감소보장', NULL, '표본조사', 'p.532', 532, 539, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-062', 'INVESTIGATION', '전수조사 (콩·팥)', 'INV-060 의 한 방법. 콩·팥만 적용. 기계수확(탈곡 포함) 또는 수확 직전 자른 작물 그대로 둔 상태 기계탈곡 농지 한정. 종실 무게 = 전체 콩·팥 종실 무게 직접 측정 또는 10포대 이상 임의 선정 평균무게 × 전체 포대수. 함수율 = 10회 이상 측정 후 평균 (각 횟수마다 다른 포대 추출).', '종합위험 밭작물 수확감소보장', NULL, '전수조사', 'p.538', 538, 545, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-063', 'INVESTIGATION', '미보상비율 조사 (밭작물)', '모든 조사 시 동시 조사 (수확감소 + 생산비보장 공통). 품목별 미보상비율 적용표(별표2) 따라 조사. 미보상감수량 = (평년수확량 - 수확량) × 미보상비율.', '종합위험 밭작물 수확감소보장', NULL, '미보상비율 조사', 'p.538', 538, 545, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-064', 'INVESTIGATION', '생산비보장 피해사실 확인조사', 'INS-22 종합위험 생산비보장 적용. 적용 품목 = 브로콜리/배추/무/파/메밀/시금치/양상추 (고추 별도). 대상 재해 = 자연재해/조수해(鳥獸害)/화재. 추가조사 필요 여부(생산비보장 손해조사/경작불능손해조사) 판단. 고사면적 확인.', '종합위험 밭작물 생산비보장', NULL, '피해사실 확인조사', 'p.550', 550, 557, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-065', 'INVESTIGATION', '생산비보장 재정식·재파종 조사', 'INS-22 생산비보장 밭작물 전 품목 적용. 전조사 = 보험금 지급대상 확인 (실제 경작면적 GPS 비교, 차이 ±1,000㎡ 또는 10% 이상 시 계약사항 변경). 후조사 = 이행완료 여부 + 일부만 이행 시 미이행 면적 제외. 전조사 생략 후조사 시 면적조사 가능.', '종합위험 밭작물 생산비보장', NULL, '재정식·재파종 조사', 'p.551', 551, 558, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-066', 'INVESTIGATION', '생산비보장 경작불능조사', 'INS-22 적용 품목 = 배추/무/파/메밀/시금치/양상추. 보험기간 = ''계약체결일 24시''와 ''정식·파종 완료일 24시'' 중 최근일~수확 개시일 직전. 식물체 피해율 65% 이상. 65% 미만 또는 미신청 시 생산비보장 손해조사 대상. 산지폐기 후조사 (고추·브로콜리 제외 전 품목).', '종합위험 밭작물 생산비보장', NULL, '경작불능조사', 'p.552', 552, 559, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-067', 'INVESTIGATION', '생산비보장 손해조사', 'INS-22 적용 (1) 고추/브로콜리 = 사고 접수 직후 / (2) 그 외 = 수확 직전. 일자 조사 (사고일자/수확 예정·개시·종료 일자). 피해면적조사 = GPS 면적측정기. 메밀은 도복으로 인한 피해면적 + 도복 이외 피해면적 분리 조사. 손해정도비율 조사 = 표본이랑(고추/배추/시금치/양상추/가을무(알타리무)) 또는 표본구간(브로콜리/메밀/무(고랭지·월동·가을)/파).', '종합위험 밭작물 생산비보장', NULL, '생산비보장 손해조사', 'p.553', 553, 560, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-068', 'INVESTIGATION', '고추 표본이랑 조사 (생산비보장 손해조사 부속)', 'INV-067 부속. 표본이랑수 산정(별표1) + 표본이랑 선정 + 식재된 작물(식물체 단위) 손해정도비율표(별표6) + 고추 병충해 등급별 인정비율(별표7) 구분 조사. 피해 없거나 보장재해 외 = 정상 / 100%형 보험금 지급 완료 후 새 작물 = 평가 제외.', '종합위험 밭작물 생산비보장', NULL, '표본이랑 조사', 'p.555', 555, 562, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-069', 'INVESTIGATION', '브로콜리 작물피해율 조사', 'INV-067 부속. 표본구간수 산정(별표1) + 각 표본구간 내 연속 10구의 작물피해율 조사. 보장재해로 작물 훼손 시 피해정도에 따른 피해인정계수표 (정상 0/50%형 0.5/80%형 0.8/100%형 1) 구분. 작물피해율 = 피해송이 수 ÷ 총 송이 수.', '종합위험 밭작물 생산비보장', NULL, '작물피해율 조사', 'p.556', 556, 563, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-070', 'INVESTIGATION', '메밀 도복/도복외 면적 조사', 'INV-067 부속. 도복 이외의 면적은 표본구간수<별표1> 선정 (도복면적은 일괄 70% 손해정도비율 적용). 표본구간 = 1㎡ 원형 또는 가로·세로 1m × 1m 구획. 손해정도비율표(별표6) 구분. 피해면적 = (도복 피해면적 × 70%) + (도복 이외 피해면적 × 평균손해정도비율).', '종합위험 밭작물 생산비보장', NULL, '도복/도복외 면적 조사', 'p.557', 557, 564, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-071', 'INVESTIGATION', '인삼 최초가입 조사 (도입)', 'INS-23 작물특정 인삼손해보장 부속. 최초 가입 농지(연속하여 가입하지 않은 농지로 해가림시설 단독 가입건 제외) 가입 직후 실시. (1) 인삼 재배상태 조사 = 실제 경작면적/기 고사면적/줄기·잎 생육상태 점검 / (2) 해가림시설 상태 조사 = 계약원장 + 현지 조사표 확인 + 구조체·차광막 정상 설치 여부.', '작물특정 인삼손해보장', NULL, '최초가입 조사', 'p.568', 568, 575, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-072', 'INVESTIGATION', '인삼·해가림시설 피해사실 확인조사 (도입)', 'INS-23 + INS-24 공통. 대상 재해 = 인삼(특정위험 — 태풍/폭설/집중호우/침수/화재/우박/냉해/폭염/조수해 9종) / 해가림시설(종합위험 — 자연재해/조수해/화재 3종). 사고 접수 직후 실시. 추가조사 필요 여부(수확량조사·해가림시설손해조사) 판단. 태풍 등 재해 명확 시 생략 가능.', '작물특정 인삼손해보장', NULL, '피해사실 확인조사', 'p.569', 569, 576, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-070', 'CONCEPT', '표준 피해율 (마늘 — 10a 30,000주 기준)', '마늘 재파종/조기파종 보험금 산정의 핵심 변수. 10a당 식물체 주수 기준 = 30,000주. 표준 피해율 = (30,000 - 식물체 주수) ÷ 30,000. 한지형 마늘 = 최초 판매개시일 24시 이전 + 30,000주 미만 발생 / 난지형 마늘 = 본 산식 직접 적용 (재파종 35%) + 조기파종특약 (재파종 25%).', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.539', 539, 546, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-071', 'CONCEPT', '비대지수 (양파·마늘)', '양파/마늘 표본구간 수확량 보정용. 지역별 수확 적기보다 일찍 조사 시 잔여일수별 누적비대추정지수 적용. 양파 = 2.2%/1일. 마늘 = 0.8%/1일. 마늘은 환산계수(난지형·홍산 0.72/한지형 0.7)도 곱함. 표본구간 수확량 = 작물 무게 × (1 + 누적비대추정지수) [× 환산계수 — 마늘만].', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.533', 533, 540, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-072', 'CONCEPT', '환산계수 (마늘 — 건조 수분 보정)', '마늘 표본구간 수확량 보정용. 건조 과정에서 발생하는 수분 감소분 고려 계수. 난지형·홍산 = 0.72 / 한지형 = 0.7. CONCEPT-071 비대지수 산식의 한 항.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.533', 533, 540, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-073', 'CONCEPT', '면적피해율 (밭작물)', '재파종/재정식/생산비보장 보험금의 핵심 변수. 면적피해율 = 피해면적 ÷ 보험 가입면적 (또는 재배면적). 메밀의 경우 도복 영역 + 도복 외 영역 분리 적용 (피해면적 = 도복 × 70% + 도복외 × 평균손해정도비율). 자기부담비율 초과가 보험금 지급 트리거.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.540', 540, 547, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-074', 'CONCEPT', '준비기생산비계수 (생산비보장)', '고추 = 54.2% / 브로콜리 = 67.1%. 수확기 이전 사고의 경과비율 산정 = 준비기생산비계수 + (1 - 준비기생산비계수) × (생장일수/표준생장일수). 생장일수/표준생장일수 비율은 1을 초과할 수 없음.', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.563', 563, 570, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-075', 'CONCEPT', '표준생장일수 / 표준수확일수 (생산비보장)', '표준생장일수 = 정식일로부터 수확개시일까지 표준 일수. 고추 = 홍고추 100일 / 풋고추 70일. 브로콜리 = 130일. 표준수확일수 = 수확개시일~수확종료일. 고추 한도 = 정식완료일+150일. 생장일수 = 정식일~사고발생일. 수확일수 = 수확개시일~사고발생일.', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.563', 563, 570, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-076', 'CONCEPT', '잔존보험가입금액 (생산비보장)', '고추/브로콜리 생산비보장보험금 산식의 핵심 변수. 잔존보험가입금액 = 보험가입금액 - 보상액(기 발생 생산비보장 보험금 합계액). 자기부담금 = 잔존보험가입금액 × 자기부담비율.', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.562', 562, 569, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-077', 'CONCEPT', '평균손해정도비율 (생산비보장)', '고추/배추/무/파/시금치/양상추/메밀 피해율 산식의 핵심 변수. 피해면적을 일정 수의 표본구간/이랑으로 나누어 각 표본구간의 손해정도비율을 조사한 뒤 평균한 값. 손해정도비율표(별표6) 적용. ★ 26년 신규 — 1~10%→10%, 11~20%→20%, ..., 91~100%→100% (10단계).', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.560', 560, 567, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-078', 'CONCEPT', '작물피해율 (브로콜리)', '브로콜리 피해율 산식의 핵심 변수. 작물피해율 = 피해송이 수 ÷ 총 송이 수. 피해송이 수 = 피해송이별 피해인정계수의 합계. 피해인정계수 = 정상 0 / 50%형 0.5 / 80%형 0.8 / 100%형 1.', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.564', 564, 571, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-079', 'CONCEPT', '병충해감수량 (감자)', '감자 피해율 가산항. 병충해감수량 = 병충해 입은 괴경의 무게 × 손해정도비율 × 인정비율. 손해정도비율 = 1~10%→10%, ..., 91~100%→100% (10단계, 별표6). 인정비율 = 병·해충 등급별 (1급 90%/2급 70%/3급 50% — 별표7). 감자 피해율 = {(평년수확량 - 수확량 - 미보상감수량) + 병충해감수량} ÷ 평년수확량.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.547', 547, 554, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-080', 'CONCEPT', '병·해충 등급별 인정비율 (감자)', '감자 병충해감수량 산정의 한 항. 1급 = 90% (역병/걀쭉병/모자이크병/무름병/둘레썩음병/가루더뎅이병/잎말림병/감자뿔나방). 2급 = 70% (홍색부패병/시들음병/마른썩음병/풋마름병/줄기검은병/더뎅이병/균핵병/검은무늬썩음병/줄기기부썩음병/진딧물류/아메리카잎굴파리/방아벌레류). 3급 = 50% (반쪽시들음병/흰비단병/잿빛곰팡이병/탄저병/겹둥근무늬병/오이총채벌레/뿌리혹선충/파밤나방/큰28점박이무당벌레/기타).', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.548', 548, 555, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-081', 'CONCEPT', '손해정도비율 (생산비보장 일반 — 26년 신규 10단계)', '★ 26년 개정 핵심 (4월8일 변경사항정리 §손해정도비율 — 생산비보장(노지) 및 시설작물 20% 구간에서 10% 구간으로 변경 / 단 2-1 버섯제외). 1~10%→10%, 11~20%→20%, 21~30%→30%, 31~40%→40%, 41~50%→50%, 51~60%→60%, 61~70%→70%, 71~80%→80%, 81~90%→90%, 91~100%→100% (10단계). 26년 이전 = 5단계 (20%/40%/60%/80%/100%) 추정. 별표6 정의.', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.560', 560, 567, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 10, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-082', 'CONCEPT', '표본구간 수확량 합계 (작물별 산정 방법)', 'INV-061 표본조사의 산식 통합 노드. 작물별 variant — 감자/수박(노지)/생강/단호박/가을무(일반무)/가을배추(병충해보장형 포함) = 무게 합계 / 양배추·당근 = 정상 + 80%형 × 0.2 / 차(茶) = 새싹 무게/수확수 × (기수확수 × 기수확지수) + 새싹 무게 / 양파·마늘 = 무게 × (1 + 누적비대지수) [× 환산계수 — 마늘만] / 고구마 = 정상 + 50%형 × 0.5 + 80%형 × 0.2 / 옥수수 = (하 + 중 × 0.5) × 표준중량 × 재식시기지수 × 재식밀도지수 / 콩·팥 = 종실중량 × (1 - 함수율) ÷ 0.86 / 참깨 = ÷ 0.9 / 녹두 = ÷ 0.87.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.544', 544, 551, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-083', 'CONCEPT', '수확량 산정 (밭작물 표본조사)', '표본구간 수확량 합계를 표본구간 면적 합계로 나눈 후 표본조사 대상 면적 합계를 곱한 값에 (평년수확량/실제경작면적 × (타작물·미보상 + 기수확면적 합))을 더하여 산정. 면적 = 실경작면적 - 수확불능(고사) - 타작물·미보상 - 기수확.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.543', 543, 550, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-084', 'CONCEPT', '미보상감수량 (밭작물)', '수확감소 피해율 산식의 한 항. 미보상감수량 = (평년수확량 - 수확량) × 미보상비율. 보장재해 외 사유로 인한 감수량 보정 — 평년수확량과 수확량 차이의 일부를 미보상으로 인정.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.547', 547, 554, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-085', 'CONCEPT', '자기부담비율별 보장비율 (수확감소 1군/2군)', 'INS-21 경작불능보험금 산정의 핵심 표. 1군 (10%형 45/15%형 42/20%형 40/30%형 35/40%형 30%) 적용 = 고구마/옥수수/감자(봄/고랭지/가을재배)/마늘/콩/양파/단호박/당근(가을·월동)/팥/양배추. 2군 (-/-/40/35/30%) 적용 = 수박/참깨/당근(고랭지)/생강/녹두/가을배추/가을배추(병충해보장형)/가을무(일반무). 1군은 5등급 / 2군은 3등급(20·30·40만).', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.541', 541, 548, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-086', 'CONCEPT', '사료용 옥수수 보장비율 / 경과비율', 'INS-21 사료용 옥수수 경작불능보험금 산정의 두 변수. 보장비율 = 45%형 45/42%형 42/40%형 40/35%형 35/30%형 30 (5등급 가입 시 선택). 경과비율 = 5월 80%/6월 80%/7월 90%/8월 100%. 사료용 옥수수 경작불능보험금 = 보험가입금액 × 보장비율 × 경과비율.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.542', 542, 549, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-087', 'CONCEPT', '벼/밀/보리/귀리 자기부담비율별 경작불능 지급비율', 'INS-15(BATCH-3) 논작물 경작불능보험금 산정의 핵심 표 (본 BATCH 영역 p.518에서 확인). 10%형 45/15%형 42/20%형 40/30%형 35/40%형 30%. 귀리는 20·30·40%형만 적용 (3등급).', '논작물 수확감소보장', NULL, NULL, 'p.518', 518, 525, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-088', 'CONCEPT', '벼 수확불능보험금 자기부담비율별 비율', 'INS-15(BATCH-3) 벼 수확불능보험금 (본 BATCH 영역 p.521에서 확인) — 10%형 60/15%형 57/20%형 55/30%형 50/40%형 45%. 보험가입금액 × 위 비율. 벼 제현율 65%(분질미 70%) 미만이고 정상 출하 불가 + 계약자 신청.', '논작물 수확감소보장', NULL, NULL, 'p.521', 521, 528, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-089', 'CONCEPT', '한지형 마늘 최초 판매개시일 / 재파종 한계일', 'INS-25 마늘 조기파종특약의 트리거. 한지형 마늘 최초 판매개시일 24시 이전 사고 + 10월 31일 이전 재파종 = 조기파종특약 적용 (난지형 마늘만). 본 트리거는 INS-21 일반 재파종(마늘 — 35%) 와 다른 25% 적용.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.539', 539, 546, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-090', 'CONCEPT', '마늘 조기파종특약 자기부담비율별 경작불능 보장비율', 'INS-25 부속. 한지형 마늘 최초 판매개시일 24시 이전 + 식물체 피해율 65% 이상 + 산지폐기 확인 시 지급. 10%형 32/15%형 30/20%형 28/30%형 25/40%형 25%. INS-21 일반 보장비율(45/42/40/35/30%)과 다름.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.539', 539, 546, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-091', 'CONCEPT', '자기부담비율별 경작불능보험금 (생산비보장)', 'INS-22 적용 (배추/무/파/메밀/시금치/양상추). 10%형 45/15%형 42/20%형 40/30%형 35/40%형 30% (보험가입금액 × 비율). 양상추 = 20%/30%/40%형만 적용. INS-21 1군과 동일 비율이나 적용 품목 분리.', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.561', 561, 568, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-092', 'CONCEPT', '차(茶) 기수확지수표 (10단계)', '차(茶) 표본구간 수확량 산정의 보정. 기수확비율 (기수확 새싹수 / 전체 새싹수) 에 따라 기수확지수 결정 — 10% 미만 1.000, 10~20% 0.992, 20~30% 0.983, 30~40% 0.975, 40~50% 0.966, 50~60% 0.958, 60~70% 0.949, 70~80% 0.941, 80~90% 0.932, 90% 이상 0.924.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.546', 546, 553, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-093', 'CONCEPT', '옥수수 표준중량·재식시기지수·재식밀도지수', '옥수수 표본구간 피해수확량 = (하 항목 개수 + 중 항목 개수 × 0.5) × 품종별 표준중량 × 재식시기지수 × 재식밀도지수. 표준중량(g): 미백2호 180 / 대학찰(연농2호) 160 / 미흑찰 등 190. 재식시기지수·재식밀도지수는 약관 별표 영역 (본 BATCH 미수록).', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.545', 545, 552, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-094', 'CONCEPT', '조사료용 벼 보장비율 / 경과비율', 'INS-15(BATCH-3) 조사료용 벼 경작불능보험금의 두 변수 (본 BATCH 영역 p.518~519). 보장비율 = 45%형 45/42%형 42/40%형 40/35%형 35/30%형 30. 경과비율 = 5월 80%/6월 85%/7월 90%/8월 100%. 사료용 옥수수와 다름 (사료용 옥수수 = 5월 80%/6월 80%/7월 90%/8월 100%).', '논작물 수확감소보장', NULL, NULL, 'p.519', 519, 526, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-4', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-033', 'TERM', '식물체 주수 / 표준 피해율', '마늘·재파종 보험금 산정의 단위. 식물체 주수 = 농지에 식재된 마늘 식물체 개수. 10a당 = 단위면적 환산. 표준 피해율 = (30,000 - 식물체 주수) ÷ 30,000 — 30,000은 정상 식재 밀도 기준 (10a 당).', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.539', 539, 546, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-034', 'TERM', '표본이랑', '생산비보장 손해조사 단위. 고추/배추/시금치/양상추/가을무(알타리무) = 표본이랑별 식재된 작물(식물체 단위) 손해정도비율 조사. 시금치/가을무(알타리무) = 표본이랑 길이 1m 간격 구획 평가.', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.558', 558, 565, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-035', 'TERM', '표본구간 (밭작물) — 이랑 길이 × 이랑 폭', 'INV-061 의 단위. 표본구간 면적 = 이랑길이 × 이랑폭. 작물별 표본구간 면적 산정 방법 (양파·마늘/단호박·당근/고구마·양배추·감자·옥수수/차(茶)/콩·팥/수박(노지)/가을배추/참깨/가을무/생강/녹두). 콩·팥은 점파 4주 이상 또는 산파 1㎡ 원형.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.533', 533, 540, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-036', 'TERM', '종실중량 / 함수율', '콩·팥/참깨/녹두 표본조사 + 전수조사의 단위. 표본 종실중량 = 표본구간 종실 무게 (꼬투리 제거 후). 함수율 = 종실 수분 비율 (3회 평균 — 표본조사 / 10회 이상 평균 — 전수조사). 종실중량 × (1 - 함수율) ÷ 작물별 분모 (콩·팥 0.86 / 참깨 0.9 / 녹두 0.87) = 표준 수확량.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.545', 545, 552, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-037', 'TERM', '비대 종료 / 결구 형성 완료', '수확량조사 적기 판단의 시점 용어. 비대 종료 = 양파 도복 완료 / 마늘 잎과 줄기 1/2~2/3 황변 마름 / 고구마 삽식+120일 / 감자 파종+95~110일 / 생강 파종+180일. 결구 형성 완료 = 양배추 / 가을배추 / 가을무(일반무) 수확 적기.', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.530', 530, 537, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-038', 'TERM', '신초 (1심2엽) / 기수확지수 (차(茶))', '차(茶) 수확량조사의 단위. 신초 = 새로 자란 새싹. 1심2엽 = 정상 수확 단위. 신초장 4.8cm 이상/엽장 2.8cm 이상/엽폭 0.9cm 이상 형성 시점 = 수확 가능. 기수확지수 = 기수확비율(기수확 새싹수 / 전체 새싹수)에 따른 보정 계수 (10단계, 0.924~1.000).', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.530', 530, 537, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-61', 'FORMULA', '벼 이앙·직파불능 보험금', '산식: insurance_amount * 0.15. 변수 정의: {"insurance_amount":"보험가입금액 number>=0"}', '논작물 수확감소보장', NULL, NULL, 'p.517', 517, 524, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-62', 'FORMULA', '벼 재이앙·재직파 보험금', '산식: insurance_amount * 0.25 * area_damage_rate. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","area_damage_rate":"면적피해율(피해면적÷보험가입면적) number 0..1, 트리거 > 0.10"}', '논작물 수확감소보장', NULL, NULL, 'p.518', 518, 525, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-63', 'FORMULA', '면적피해율 (논·밭작물 공통)', '산식: damage_area / insured_area. 변수 정의: {"damage_area":"피해면적 number>=0","insured_area":"보험가입면적 number>0"}', '논작물 수확감소보장', NULL, NULL, 'p.518', 518, 525, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-64', 'FORMULA', '조사료용 벼 경작불능 보험금', '산식: insurance_amount * coverage_rate * progress_rate. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","coverage_rate":"보장비율(45%형 0.45 / 42%형 0.42 / 40%형 0.40 / 35%형 0.35 / 30%형 0.30) number 0..1","progress_rate":"경과비율(5월 0.80 / 6월 0.85 / 7월 0.90 / 8월 1.00) number 0..1"}', '논작물 수확감소보장', NULL, NULL, 'p.518', 518, 525, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-65', 'FORMULA', '논작물 수확감소보험금', '산식: insurance_amount * (damage_rate - deductible_rate). 변수 정의: {"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율 number 0..1","deductible_rate":"자기부담비율 number 0..1"}', '논작물 수확감소보장', NULL, NULL, 'p.520', 520, 527, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-66', 'FORMULA', '수확감소 피해율 (논작물 일반)', '산식: (reference_yield - actual_yield - uncovered_loss) / reference_yield. 변수 정의: {"reference_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_loss":"미보상감수량 number>=0"}', '논작물 수확감소보장', NULL, NULL, 'p.520', 520, 527, '제2편 농작물재해보험 손해평가', '제3절 논작물(벼, 맥류) 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-67', 'FORMULA', '마늘 조기파종 재파종 보험금 (난지형)', '산식: insurance_amount * 0.25 * standard_damage_rate. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","standard_damage_rate":"표준 피해율(F-68 결과) number 0..1"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.539', 539, 546, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-68', 'FORMULA', '마늘 표준 피해율 (10a 30,000주 기준)', '산식: (30000 - plant_count_per_10a) / 30000. 변수 정의: {"plant_count_per_10a":"10a당 식물체 주수 integer>=0"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.539', 539, 546, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-69', 'FORMULA', '마늘 재파종 보험금 (난지형 일반)', '산식: insurance_amount * 0.35 * standard_damage_rate. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","standard_damage_rate":"표준 피해율(F-68 결과) number 0..1"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.540', 540, 547, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-70', 'FORMULA', '당근(고랭지/가을·월동) 재파종 보험금', '산식: insurance_amount * 0.15 * area_damage_rate. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","area_damage_rate":"면적피해율(F-63 결과) number 0..1, 트리거 > 자기부담비율"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.540', 540, 547, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-71', 'FORMULA', '가을무·감자(가을재배) 재파종 보험금 ★ 26년 신규', '산식: insurance_amount * 0.20 * area_damage_rate. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","area_damage_rate":"면적피해율(F-63 결과) number 0..1, 트리거 > 자기부담비율"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.540', 540, 547, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-72', 'FORMULA', '재정식보험금 (양배추/단호박/가을배추/양파)', '산식: insurance_amount * 0.20 * area_damage_rate. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","area_damage_rate":"면적피해율(F-63 결과) number 0..1, 트리거 > 자기부담비율"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.540', 540, 547, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-73', 'FORMULA', '밭작물 경작불능 보험금 (수확감소 — 사료용 옥수수 제외)', '산식: insurance_amount * coverage_rate. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","coverage_rate":"자기부담비율별 보장비율 (1군: 10%형 0.45/15%형 0.42/20%형 0.40/30%형 0.35/40%형 0.30 — 고구마/옥수수/감자/마늘/콩/양파/단호박/당근(가을·월동)/팥/양배추) (2군: -/-/0.40/0.35/0.30 — 수박/참깨/당근(고랭지)/생강/녹두/가을배추/가을무) number 0..1"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.541', 541, 548, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-74', 'FORMULA', '사료용 옥수수 경작불능 보험금', '산식: insurance_amount * coverage_rate * progress_rate. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","coverage_rate":"보장비율(45%형 0.45 / 42%형 0.42 / 40%형 0.40 / 35%형 0.35 / 30%형 0.30) number 0..1","progress_rate":"경과비율(5월 0.80 / 6월 0.80 / 7월 0.90 / 8월 1.00) number 0..1"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.541', 541, 548, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-75', 'FORMULA', '밭작물 수확감소 보험금 (일반)', '산식: insurance_amount * (damage_rate - deductible_rate). 변수 정의: {"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(F-76 결과 또는 F-77 감자) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.542', 542, 549, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-76', 'FORMULA', '수확감소 피해율 (밭작물 일반)', '산식: (reference_yield - actual_yield - uncovered_loss) / reference_yield. 변수 정의: {"reference_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_loss":"미보상감수량(F-81 결과) number>=0"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.542', 542, 549, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-77', 'FORMULA', '감자 피해율 (병충해 가산)', '산식: ((reference_yield - actual_yield - uncovered_loss) + pest_loss) / reference_yield. 변수 정의: {"reference_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_loss":"미보상감수량(F-81 결과) number>=0","pest_loss":"병충해감수량(F-82 결과) number>=0"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.543', 543, 550, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-78', 'FORMULA', '옥수수 수확감소 보험금 (특수)', '산식: min(insurance_amount, loss_amount) - deductible_amount. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","loss_amount":"손해액(F-79 결과) number>=0","deductible_amount":"자기부담금(insurance_amount × 자기부담비율) number>=0"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.543', 543, 550, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-79', 'FORMULA', '옥수수 손해액', '산식: damage_yield * subscription_price. 변수 정의: {"damage_yield":"피해수확량(F-80 표본구간 환산 — 미보상감수량 제외) number>=0","subscription_price":"가입가격 number>0"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.543', 543, 550, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-80', 'FORMULA', '표본조사 수확량 (밭작물 통합)', '산식: (sample_yield_sum / sample_area_sum) * survey_target_area + (reference_yield / actual_area) * (other_area + harvested_area). 변수 정의: {"sample_yield_sum":"표본구간 수확량 합계(작물별 산정 — CONCEPT-082) number>=0","sample_area_sum":"표본구간 면적 합계 number>0","survey_target_area":"조사대상 면적(=실경작면적-고사면적-타작물·미보상-기수확) number>=0","reference_yield":"평년수확량 number>0","actual_area":"실제 경작면적 number>0","other_area":"타작물 및 미보상면적 number>=0","harvested_area":"기수확면적 number>=0"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.543', 543, 550, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-81', 'FORMULA', '미보상감수량 (밭작물)', '산식: (reference_yield - actual_yield) * uncovered_ratio. 변수 정의: {"reference_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_ratio":"미보상비율 number 0..1"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.547', 547, 554, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-82', 'FORMULA', '감자 병충해감수량', '산식: infected_tuber_weight * damage_severity_rate * accept_ratio. 변수 정의: {"infected_tuber_weight":"병충해 입은 괴경의 무게 number>=0","damage_severity_rate":"손해정도비율 (1~10%→0.10, ..., 91~100%→1.00) number 0..1","accept_ratio":"인정비율 (1급 0.90 / 2급 0.70 / 3급 0.50) number 0..1"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.547', 547, 554, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-83', 'FORMULA', '콩·팥 전수 표준 수확량', '산식: total_seed_weight * (1 - moisture_rate) / 0.86. 변수 정의: {"total_seed_weight":"전체 종실 중량 number>=0","moisture_rate":"함수율(10회 평균) number 0..1"}', '종합위험 밭작물 수확감소보장', NULL, NULL, 'p.548', 548, 555, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-84', 'FORMULA', '재파종·재정식 보험금 (생산비보장 전 품목)', '산식: insurance_amount * 0.20 * area_damage_rate. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","area_damage_rate":"면적피해율(F-63 결과) number 0..1, 트리거 > 자기부담비율"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.561', 561, 568, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-85', 'FORMULA', '경작불능 보험금 (생산비보장 — 배추/무/파/메밀/시금치/양상추)', '산식: insurance_amount * coverage_rate. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","coverage_rate":"자기부담비율별 보장비율 (10%형 0.45/15%형 0.42/20%형 0.40/30%형 0.35/40%형 0.30; 양상추 = 20·30·40형만) number 0..1"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.561', 561, 568, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-86', 'FORMULA', '고추 생산비보장 보험금 (병충해 없음)', '산식: (remaining_insurance * progress_rate * damage_rate) - deductible_amount. 변수 정의: {"remaining_insurance":"잔존보험가입금액(F-87 결과) number>=0","progress_rate":"경과비율(F-90 수확기 이전 / F-91 수확기 중) number 0..1","damage_rate":"피해율(F-92 결과) number 0..1","deductible_amount":"자기부담금(F-88 결과) number>=0"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.562', 562, 569, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-87', 'FORMULA', '잔존보험가입금액 (생산비보장)', '산식: insurance_amount - prior_payouts. 변수 정의: {"insurance_amount":"보험가입금액 number>=0","prior_payouts":"기 발생 생산비보장 보험금 합계액 number>=0"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.562', 562, 569, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-88', 'FORMULA', '자기부담금 (생산비보장)', '산식: remaining_insurance * deductible_rate. 변수 정의: {"remaining_insurance":"잔존보험가입금액(F-87 결과) number>=0","deductible_rate":"자기부담비율 number 0..1"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.562', 562, 569, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-89', 'FORMULA', '고추 생산비보장 보험금 (병충해 있음 — 노지 고추만)', '산식: (remaining_insurance * progress_rate * damage_rate * pest_grade_ratio) - deductible_amount. 변수 정의: {"remaining_insurance":"잔존보험가입금액(F-87 결과) number>=0","progress_rate":"경과비율(F-90 수확기 이전 / F-91 수확기 중) number 0..1","damage_rate":"피해율(F-92 결과) number 0..1","pest_grade_ratio":"병충해 등급별 인정비율 number 0..1","deductible_amount":"자기부담금(F-88 결과) number>=0"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.562', 562, 569, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-90', 'FORMULA', '경과비율 (생산비보장 — 수확기 이전, 고추/브로콜리)', '산식: preparation_coefficient + (1 - preparation_coefficient) * min(growth_days / standard_growth_days, 1.0). 변수 정의: {"preparation_coefficient":"준비기생산비계수(고추 0.542 / 브로콜리 0.671) number 0..1","growth_days":"생장일수(정식일~사고발생일) integer>=0","standard_growth_days":"표준생장일수(고추 홍 100/풋 70 / 브로콜리 130) integer>0"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.563', 563, 570, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-91', 'FORMULA', '경과비율 (생산비보장 — 수확기 중, 고추/브로콜리)', '산식: 1 - (harvest_days / standard_harvest_days). 변수 정의: {"harvest_days":"수확일수(수확개시일~사고발생일) integer>=0","standard_harvest_days":"표준수확일수(수확개시일~수확종료일, 고추 한도 정식완료일+150일) integer>0"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.563', 563, 570, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-92', 'FORMULA', '고추 피해율', '산식: area_damage_rate * average_damage_severity_rate * (1 - uncovered_ratio). 변수 정의: {"area_damage_rate":"면적피해율(피해면적(주수)÷재배면적(주수)) number 0..1","average_damage_severity_rate":"평균손해정도비율(표본구간별 손해정도비율 평균, 10단계) number 0..1","uncovered_ratio":"미보상비율 number 0..1"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.563', 563, 570, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-93', 'FORMULA', '브로콜리 생산비보장 보험금', '산식: (remaining_insurance * progress_rate * damage_rate) - deductible_amount. 변수 정의: {"remaining_insurance":"잔존보험가입금액(F-87 결과) number>=0","progress_rate":"경과비율(F-90 수확기 이전 / F-91 수확기 중) number 0..1","damage_rate":"피해율(F-94 결과) number 0..1","deductible_amount":"자기부담금(F-88 결과) number>=0"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.564', 564, 571, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-94', 'FORMULA', '브로콜리 피해율', '산식: area_damage_rate * crop_damage_rate * (1 - uncovered_ratio). 변수 정의: {"area_damage_rate":"면적피해율(피해면적(㎡)÷재배면적(㎡)) number 0..1","crop_damage_rate":"작물피해율(=피해송이 수÷총 송이 수, 피해인정계수 합계 / 정상 0/50%형 0.5/80%형 0.8/100%형 1) number 0..1","uncovered_ratio":"미보상비율 number 0..1"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.564', 564, 571, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-95', 'FORMULA', '메밀 생산비보장 보험금', '산식: insurance_amount * (damage_rate - deductible_rate). 변수 정의: {"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(F-96 결과) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.565', 565, 572, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-96', 'FORMULA', '메밀 피해율 + 면적피해율 (도복/도복외 통합)', '산식: ((lodge_area * 0.70) + (non_lodge_area * average_damage_severity_rate)) / planted_area * (1 - uncovered_ratio). 변수 정의: {"lodge_area":"도복으로 인한 피해면적 number>=0","non_lodge_area":"도복 이외 피해면적 number>=0","average_damage_severity_rate":"평균손해정도비율(도복 외 표본구간별 손해정도비율 평균, 10단계) number 0..1","planted_area":"재배면적 number>0","uncovered_ratio":"미보상비율 number 0..1"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.565', 565, 572, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-97', 'FORMULA', '배추·무·파·시금치·양상추 생산비보장 보험금 + 피해율', '산식: insurance_amount * ((damage_area / planted_area * average_damage_severity_rate * (1 - uncovered_ratio)) - deductible_rate). 변수 정의: {"insurance_amount":"보험가입금액 number>=0","damage_area":"피해면적 number>=0","planted_area":"재배면적 number>0","average_damage_severity_rate":"평균손해정도비율(표본이랑/표본구간 손해정도비율 평균, 10단계) number 0..1","uncovered_ratio":"미보상비율 number 0..1","deductible_rate":"자기부담비율 number 0..1"}', '종합위험 밭작물 생산비보장', NULL, NULL, 'p.565', 565, 572, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-4', 2026, 9, 'draft');

-- 2. formulas (37 rows, INSERT OR IGNORE — 기존 등록 row 보존)
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-61', '벼 이앙·직파불능 보험금', 'insurance_amount * 0.15', '{"insurance_amount":"보험가입금액 number>=0"}', 'p.517', 'F-61', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-62', '벼 재이앙·재직파 보험금', 'insurance_amount * 0.25 * area_damage_rate', '{"insurance_amount":"보험가입금액 number>=0","area_damage_rate":"면적피해율(피해면적÷보험가입면적) number 0..1, 트리거 > 0.10"}', 'p.518', 'F-62', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-63', '면적피해율 (논·밭작물 공통)', 'damage_area / insured_area', '{"damage_area":"피해면적 number>=0","insured_area":"보험가입면적 number>0"}', 'p.518', 'F-63', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-64', '조사료용 벼 경작불능 보험금', 'insurance_amount * coverage_rate * progress_rate', '{"insurance_amount":"보험가입금액 number>=0","coverage_rate":"보장비율(45%형 0.45 / 42%형 0.42 / 40%형 0.40 / 35%형 0.35 / 30%형 0.30) number 0..1","progress_rate":"경과비율(5월 0.80 / 6월 0.85 / 7월 0.90 / 8월 1.00) number 0..1"}', 'p.518', 'F-64', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-65', '논작물 수확감소보험금', 'insurance_amount * (damage_rate - deductible_rate)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율 number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.520', 'F-65', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-66', '수확감소 피해율 (논작물 일반)', '(reference_yield - actual_yield - uncovered_loss) / reference_yield', '{"reference_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_loss":"미보상감수량 number>=0"}', 'p.520', 'F-66', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-67', '마늘 조기파종 재파종 보험금 (난지형)', 'insurance_amount * 0.25 * standard_damage_rate', '{"insurance_amount":"보험가입금액 number>=0","standard_damage_rate":"표준 피해율(F-68 결과) number 0..1"}', 'p.539', 'F-67', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-68', '마늘 표준 피해율 (10a 30,000주 기준)', '(30000 - plant_count_per_10a) / 30000', '{"plant_count_per_10a":"10a당 식물체 주수 integer>=0"}', 'p.539', 'F-68', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-69', '마늘 재파종 보험금 (난지형 일반)', 'insurance_amount * 0.35 * standard_damage_rate', '{"insurance_amount":"보험가입금액 number>=0","standard_damage_rate":"표준 피해율(F-68 결과) number 0..1"}', 'p.540', 'F-69', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-70', '당근(고랭지/가을·월동) 재파종 보험금', 'insurance_amount * 0.15 * area_damage_rate', '{"insurance_amount":"보험가입금액 number>=0","area_damage_rate":"면적피해율(F-63 결과) number 0..1, 트리거 > 자기부담비율"}', 'p.540', 'F-70', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-71', '가을무·감자(가을재배) 재파종 보험금 ★ 26년 신규', 'insurance_amount * 0.20 * area_damage_rate', '{"insurance_amount":"보험가입금액 number>=0","area_damage_rate":"면적피해율(F-63 결과) number 0..1, 트리거 > 자기부담비율"}', 'p.540', 'F-71', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-72', '재정식보험금 (양배추/단호박/가을배추/양파)', 'insurance_amount * 0.20 * area_damage_rate', '{"insurance_amount":"보험가입금액 number>=0","area_damage_rate":"면적피해율(F-63 결과) number 0..1, 트리거 > 자기부담비율"}', 'p.540', 'F-72', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-73', '밭작물 경작불능 보험금 (수확감소 — 사료용 옥수수 제외)', 'insurance_amount * coverage_rate', '{"insurance_amount":"보험가입금액 number>=0","coverage_rate":"자기부담비율별 보장비율 (1군: 10%형 0.45/15%형 0.42/20%형 0.40/30%형 0.35/40%형 0.30 — 고구마/옥수수/감자/마늘/콩/양파/단호박/당근(가을·월동)/팥/양배추) (2군: -/-/0.40/0.35/0.30 — 수박/참깨/당근(고랭지)/생강/녹두/가을배추/가을무) number 0..1"}', 'p.541', 'F-73', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-74', '사료용 옥수수 경작불능 보험금', 'insurance_amount * coverage_rate * progress_rate', '{"insurance_amount":"보험가입금액 number>=0","coverage_rate":"보장비율(45%형 0.45 / 42%형 0.42 / 40%형 0.40 / 35%형 0.35 / 30%형 0.30) number 0..1","progress_rate":"경과비율(5월 0.80 / 6월 0.80 / 7월 0.90 / 8월 1.00) number 0..1"}', 'p.541', 'F-74', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-75', '밭작물 수확감소 보험금 (일반)', 'insurance_amount * (damage_rate - deductible_rate)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(F-76 결과 또는 F-77 감자) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.542', 'F-75', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-76', '수확감소 피해율 (밭작물 일반)', '(reference_yield - actual_yield - uncovered_loss) / reference_yield', '{"reference_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_loss":"미보상감수량(F-81 결과) number>=0"}', 'p.542', 'F-76', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-77', '감자 피해율 (병충해 가산)', '((reference_yield - actual_yield - uncovered_loss) + pest_loss) / reference_yield', '{"reference_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_loss":"미보상감수량(F-81 결과) number>=0","pest_loss":"병충해감수량(F-82 결과) number>=0"}', 'p.543', 'F-77', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-78', '옥수수 수확감소 보험금 (특수)', 'min(insurance_amount, loss_amount) - deductible_amount', '{"insurance_amount":"보험가입금액 number>=0","loss_amount":"손해액(F-79 결과) number>=0","deductible_amount":"자기부담금(insurance_amount × 자기부담비율) number>=0"}', 'p.543', 'F-78', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-79', '옥수수 손해액', 'damage_yield * subscription_price', '{"damage_yield":"피해수확량(F-80 표본구간 환산 — 미보상감수량 제외) number>=0","subscription_price":"가입가격 number>0"}', 'p.543', 'F-79', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-80', '표본조사 수확량 (밭작물 통합)', '(sample_yield_sum / sample_area_sum) * survey_target_area + (reference_yield / actual_area) * (other_area + harvested_area)', '{"sample_yield_sum":"표본구간 수확량 합계(작물별 산정 — CONCEPT-082) number>=0","sample_area_sum":"표본구간 면적 합계 number>0","survey_target_area":"조사대상 면적(=실경작면적-고사면적-타작물·미보상-기수확) number>=0","reference_yield":"평년수확량 number>0","actual_area":"실제 경작면적 number>0","other_area":"타작물 및 미보상면적 number>=0","harvested_area":"기수확면적 number>=0"}', 'p.543', 'F-80', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-81', '미보상감수량 (밭작물)', '(reference_yield - actual_yield) * uncovered_ratio', '{"reference_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_ratio":"미보상비율 number 0..1"}', 'p.547', 'F-81', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-82', '감자 병충해감수량', 'infected_tuber_weight * damage_severity_rate * accept_ratio', '{"infected_tuber_weight":"병충해 입은 괴경의 무게 number>=0","damage_severity_rate":"손해정도비율 (1~10%→0.10, ..., 91~100%→1.00) number 0..1","accept_ratio":"인정비율 (1급 0.90 / 2급 0.70 / 3급 0.50) number 0..1"}', 'p.547', 'F-82', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-83', '콩·팥 전수 표준 수확량', 'total_seed_weight * (1 - moisture_rate) / 0.86', '{"total_seed_weight":"전체 종실 중량 number>=0","moisture_rate":"함수율(10회 평균) number 0..1"}', 'p.548', 'F-83', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-84', '재파종·재정식 보험금 (생산비보장 전 품목)', 'insurance_amount * 0.20 * area_damage_rate', '{"insurance_amount":"보험가입금액 number>=0","area_damage_rate":"면적피해율(F-63 결과) number 0..1, 트리거 > 자기부담비율"}', 'p.561', 'F-84', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-85', '경작불능 보험금 (생산비보장 — 배추/무/파/메밀/시금치/양상추)', 'insurance_amount * coverage_rate', '{"insurance_amount":"보험가입금액 number>=0","coverage_rate":"자기부담비율별 보장비율 (10%형 0.45/15%형 0.42/20%형 0.40/30%형 0.35/40%형 0.30; 양상추 = 20·30·40형만) number 0..1"}', 'p.561', 'F-85', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-86', '고추 생산비보장 보험금 (병충해 없음)', '(remaining_insurance * progress_rate * damage_rate) - deductible_amount', '{"remaining_insurance":"잔존보험가입금액(F-87 결과) number>=0","progress_rate":"경과비율(F-90 수확기 이전 / F-91 수확기 중) number 0..1","damage_rate":"피해율(F-92 결과) number 0..1","deductible_amount":"자기부담금(F-88 결과) number>=0"}', 'p.562', 'F-86', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-87', '잔존보험가입금액 (생산비보장)', 'insurance_amount - prior_payouts', '{"insurance_amount":"보험가입금액 number>=0","prior_payouts":"기 발생 생산비보장 보험금 합계액 number>=0"}', 'p.562', 'F-87', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-88', '자기부담금 (생산비보장)', 'remaining_insurance * deductible_rate', '{"remaining_insurance":"잔존보험가입금액(F-87 결과) number>=0","deductible_rate":"자기부담비율 number 0..1"}', 'p.562', 'F-88', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-89', '고추 생산비보장 보험금 (병충해 있음 — 노지 고추만)', '(remaining_insurance * progress_rate * damage_rate * pest_grade_ratio) - deductible_amount', '{"remaining_insurance":"잔존보험가입금액(F-87 결과) number>=0","progress_rate":"경과비율(F-90 수확기 이전 / F-91 수확기 중) number 0..1","damage_rate":"피해율(F-92 결과) number 0..1","pest_grade_ratio":"병충해 등급별 인정비율 number 0..1","deductible_amount":"자기부담금(F-88 결과) number>=0"}', 'p.562', 'F-89', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-90', '경과비율 (생산비보장 — 수확기 이전, 고추/브로콜리)', 'preparation_coefficient + (1 - preparation_coefficient) * min(growth_days / standard_growth_days, 1.0)', '{"preparation_coefficient":"준비기생산비계수(고추 0.542 / 브로콜리 0.671) number 0..1","growth_days":"생장일수(정식일~사고발생일) integer>=0","standard_growth_days":"표준생장일수(고추 홍 100/풋 70 / 브로콜리 130) integer>0"}', 'p.563', 'F-90', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-91', '경과비율 (생산비보장 — 수확기 중, 고추/브로콜리)', '1 - (harvest_days / standard_harvest_days)', '{"harvest_days":"수확일수(수확개시일~사고발생일) integer>=0","standard_harvest_days":"표준수확일수(수확개시일~수확종료일, 고추 한도 정식완료일+150일) integer>0"}', 'p.563', 'F-91', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-92', '고추 피해율', 'area_damage_rate * average_damage_severity_rate * (1 - uncovered_ratio)', '{"area_damage_rate":"면적피해율(피해면적(주수)÷재배면적(주수)) number 0..1","average_damage_severity_rate":"평균손해정도비율(표본구간별 손해정도비율 평균, 10단계) number 0..1","uncovered_ratio":"미보상비율 number 0..1"}', 'p.563', 'F-92', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-93', '브로콜리 생산비보장 보험금', '(remaining_insurance * progress_rate * damage_rate) - deductible_amount', '{"remaining_insurance":"잔존보험가입금액(F-87 결과) number>=0","progress_rate":"경과비율(F-90 수확기 이전 / F-91 수확기 중) number 0..1","damage_rate":"피해율(F-94 결과) number 0..1","deductible_amount":"자기부담금(F-88 결과) number>=0"}', 'p.564', 'F-93', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-94', '브로콜리 피해율', 'area_damage_rate * crop_damage_rate * (1 - uncovered_ratio)', '{"area_damage_rate":"면적피해율(피해면적(㎡)÷재배면적(㎡)) number 0..1","crop_damage_rate":"작물피해율(=피해송이 수÷총 송이 수, 피해인정계수 합계 / 정상 0/50%형 0.5/80%형 0.8/100%형 1) number 0..1","uncovered_ratio":"미보상비율 number 0..1"}', 'p.564', 'F-94', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-95', '메밀 생산비보장 보험금', 'insurance_amount * (damage_rate - deductible_rate)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(F-96 결과) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.565', 'F-95', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-96', '메밀 피해율 + 면적피해율 (도복/도복외 통합)', '((lodge_area * 0.70) + (non_lodge_area * average_damage_severity_rate)) / planted_area * (1 - uncovered_ratio)', '{"lodge_area":"도복으로 인한 피해면적 number>=0","non_lodge_area":"도복 이외 피해면적 number>=0","average_damage_severity_rate":"평균손해정도비율(도복 외 표본구간별 손해정도비율 평균, 10단계) number 0..1","planted_area":"재배면적 number>0","uncovered_ratio":"미보상비율 number 0..1"}', 'p.565', 'F-96', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-97', '배추·무·파·시금치·양상추 생산비보장 보험금 + 피해율', 'insurance_amount * ((damage_area / planted_area * average_damage_severity_rate * (1 - uncovered_ratio)) - deductible_rate)', '{"insurance_amount":"보험가입금액 number>=0","damage_area":"피해면적 number>=0","planted_area":"재배면적 number>0","average_damage_severity_rate":"평균손해정도비율(표본이랑/표본구간 손해정도비율 평균, 10단계) number 0..1","uncovered_ratio":"미보상비율 number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.565', 'F-97', 2026);

